function textDialog(title,placeholder,value,done){open(title,`<form id="text-form"><label for="text-value">${esc(placeholder)}</label><input id="text-value" maxlength="100" required value="${esc(value)}" placeholder="${esc(placeholder)}"><button class="btn primary full">추가 / 저장하기 ↗</button></form>`);$('#text-form').onsubmit=e=>{e.preventDefault();const v=$('#text-value').value.trim();if(v){done(v);close();save();render()}}}
